local UIActivityTotalTopupCellNode = Class('UIActivityTotalTopupCellNode')
function UIActivityTotalTopupCellNode:__init()
    self.isAnimation = false 
    self.dialog = nil
    self.amount = nil
end

function UIActivityTotalTopupCellNode:__delete()
    self.isAnimation = nil
    self.dialog = nil
    self.amount = nil
end

function UIActivityTotalTopupCellNode:Awake()
    SetButtonAction(self.FontStyleButton, function ()
        local status = self:GetStatus()
        local isCan = status == Constants.GetStatus.Can
        local isGot = status == Constants.GetStatus.Has
        local isNot = status == Constants.GetStatus.Not
        if isNot then
            GameUtils.Toast(localize("暂无奖励可领取"))
            return 
        end
        if isGot then
            GameUtils.Toast(localize("奖励已经领取"))
            return
        end
        if isCan then
            GameUtils.Request(Interfaces.ActivityAccumulativePayDraw,
            {rewardId = self.data.id , activityUuid = self.dialog.activityDt.id} ,
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    local data = response.data 
                    local rewards = data.rewards  
                    GoodsUtils.DrawRewards(checkTable(rewards), true)
                    UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                    )
                    self.data.status = Constants.GetStatus.Has
                    self.dialog:UpdateRedPoint()
                    self:RefreshStatue()
                end
            end)
        end
    end)
end

function UIActivityTotalTopupCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function UIActivityTotalTopupCellNode:GetStatus()
    return checkInt(self.data.status) 
end
------------------------------------------------------ public
---@param dialog UIActivityTotalTopupPanel
function UIActivityTotalTopupCellNode:Refresh(data, index , amount , dialog)
    self.amount = amount 
    self.dialog = dialog 
    if self.isAnimation then
        self:PlayInitAnim()
    else 
        self:PlayFadeInAnim(index)
        self.isAnimation = true
    end
    self.data = data
    --local needCount = data.amount - self.amount
    --self.TxtNumber.text = needCount > 0 and needCount or 0
    self.TxtNumber.text = string.format("%d/%s", self.amount, checkNumber(data.amount))
    -- refresh reward
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    
    self.CommonGoodsList.Env:FreshBaseUI(self.data.rewards)

    -- updateStatue
    self:RefreshStatue()
end

function UIActivityTotalTopupCellNode:RefreshStatue()
    local status = self:GetStatus() 
    local isCan = status == Constants.GetStatus.Can
    local isGot = status == Constants.GetStatus.Has
    local isNot = status == Constants.GetStatus.Not
    -- refresh reward
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    KTool.SetActive(self.FontStyleButton,not isGot)
    KTool.SetActive(self.ImgFinish, isGot)
    KTool.SetActive(self.Black, isGot)
    KTool.SetActive(self.CanAnim, isCan)
    KTool.SetActive(self.FloorFinish ,isGot)
    KTool.SetActive(self.FloorNormal ,not isGot)

    CfUtils.SetUISwitchImage(self.ImgFrame2, isCan and 1 or 2)
    CfUtils.SetUISwitchImage(self.ImgFrame, isCan and 1 or 2)
    if isCan then
        self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
    elseif isNot then
        self.FontStyleButton:ResetFontStyle("B13", localize("未达成"))
    end
end

function UIActivityTotalTopupCellNode:PlayFadeInAnim(index)
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Wait")
        CfUtils.PlayDelayShowAnimate(self.AnimRoot, 1, ((index or 1) - 1)  * 0.02)
    end
end

function UIActivityTotalTopupCellNode:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Default")
    end
end


return UIActivityTotalTopupCellNode
 
 